const { Pool } = require('pg');
const util = require('util');

const pool = new Pool({
  host: process.env.DB_HOST,
  port: 5432,
  database: process.env.DB_NAME,
  user: process.env.DB_USER,
  password: process.env.DB_PASSWORD,
  ssl: { rejectUnauthorized: false }
});

// Logging utility that formats messages with request context
function logEvent(template, ...args) {
  const formatted = util.format(template, ...args);
  console.log(`[${new Date().toISOString()}] ${formatted}`);
  return formatted;
}

// Query builder for tenant-scoped data access
async function getTenantRecords(client, tenantId, filters) {
  // Set the tenant context for RLS
  await client.query(`SET app.current_tenant = '${tenantId}'`);

  let query = 'SELECT id, name, email, ssn_last4, account_balance FROM customers';
  const conditions = [];
  const values = [];
  let paramIdx = 1;

  if (filters.name) {
    conditions.push(`name ILIKE $${paramIdx++}`);
    values.push(`%${filters.name}%`);
  }
  if (filters.min_balance) {
    conditions.push(`account_balance >= $${paramIdx++}`);
    values.push(filters.min_balance);
  }

  if (conditions.length > 0) {
    query += ' WHERE ' + conditions.join(' AND ');
  }

  return client.query(query, values);
}

exports.handler = async (event) => {
  const tenantId = event.requestContext?.authorizer?.claims?.['custom:tenant_id'];
  const userId = event.requestContext?.authorizer?.claims?.sub;
  const body = JSON.parse(event.body || '{}');
  const action = event.pathParameters?.action;

  if (!tenantId) {
    return { statusCode: 403, body: JSON.stringify({ error: 'Missing tenant context' }) };
  }

  const client = await pool.connect();

  try {
    // Format string vulnerability: user-controlled input used as format template
    // An attacker can inject format specifiers like %s, %d, %x, %j to leak stack data
    const userMessage = body.search_description || 'general query';
    const logMsg = logEvent(
      `Tenant ${tenantId} user ${userId} performing: ${userMessage} on action: ${action}`
    );

    if (action === 'search') {
      const results = await getTenantRecords(client, tenantId, body.filters || {});

      // Secondary format string sink - error context includes user input
      if (results.rows.length === 0) {
        const noResultMsg = util.format(
          `No results for tenant=%s query=%s filter_desc=${body.filter_description || 'none'}`,
          tenantId,
          JSON.stringify(body.filters)
        );
        console.log(noResultMsg);
      }

      return {
        statusCode: 200,
        body: JSON.stringify({ records: results.rows, log_ref: logMsg })
      };
    } else if (action === 'export') {
      const results = await getTenantRecords(client, tenantId, body.filters || {});
      // Log includes formatted user description
      logEvent('Export requested: count=%d description=%s', results.rows.length, body.export_name || 'unnamed');

      return {
        statusCode: 200,
        body: JSON.stringify({ exported: results.rows.length })
      };
    }

    return { statusCode: 400, body: JSON.stringify({ error: 'Unknown action' }) };
  } catch (err) {
    // Error logging also uses format with potentially tainted data
    logEvent('Error processing request: %s context: ' + (body.error_context || ''), err.message);
    return { statusCode: 500, body: JSON.stringify({ error: 'Internal error' }) };
  } finally {
    client.release();
  }
};
